unsafe extern "C" fn playback_region_content_changed(_: ARAModelUpdateControllerHostRef, _: ARAPlaybackRegionHostRef, _: *const ARAContentTimeRange, _: ARAContentUpdateFlags) {}
unsafe extern "C" fn document_data_changed(_: ARAModelUpdateControllerHostRef) {}

/// One plug-in's ARA factory opened from its CLAP entry; the library stays loaded while this lives.
struct Opened {
    /// Held, not read: the plug-in's code stays loaded while its factory and document are in use.
    _lib: libloading::Library,
    entry: *const clap_plugin_entry,
    deinit: Option<unsafe extern "C" fn()>,
    factory: *const ARAFactory,
    plugin_id: String,
}

impl Drop for Opened {
    fn drop(&mut self) {
        if let Some(deinit) = self.deinit {
            unsafe { deinit() };
        }
    }
}

unsafe fn open(path: &Path) -> Result<Opened, String> {
    let lib = libloading::Library::new(path).map_err(|e| format!("cannot load {}: {e}", path.display()))?;
    let entry: libloading::Symbol<*const clap_plugin_entry> = lib.get(b"clap_entry\0").map_err(|e| format!("no clap_entry: {e}"))?;
    let entry = &**entry;
    let cpath = CString::new(path.to_string_lossy().as_bytes()).map_err(|e| e.to_string())?;
    if !(entry.init.ok_or("entry without init")?)(cpath.as_ptr()) {
        return Err("the plug-in's entry refused to initialise".into());
    }
    let deinit = entry.deinit;
    let get = entry.get_factory.ok_or("entry without get_factory")?;
    let mut ara = get(CLAP_EXT_ARA_FACTORY.as_ptr()) as *const clap_ara_factory;
    if ara.is_null() {
        ara = get(CLAP_EXT_ARA_FACTORY_COMPAT.as_ptr()) as *const clap_ara_factory;
    }
    let factory = if ara.is_null() { std::ptr::null() } else { (*ara).get_ara_factory.map(|g| g(ara, 0)).unwrap_or(std::ptr::null()) };
    let plugin_id = if ara.is_null() { String::new() } else { (*ara).get_plugin_id.map(|g| text(g(ara, 0))).unwrap_or_default() };
    let opened = Opened { _lib: lib, entry: entry as *const clap_plugin_entry, deinit, factory, plugin_id };
    if opened.factory.is_null() {
        return Err("the plug-in offers no ARA factory".into());
    }
    Ok(opened)
}

/// The host side of one document: its four interfaces and the instance the plug-in is given. Boxed, so the instance's
/// pointers to the interfaces stay put while the plug-in holds them.
struct Host {
    audio_access: ARAAudioAccessControllerInterface,
    archiving: ARAArchivingControllerInterface,
    content_access: ARAContentAccessControllerInterface,
    model_update: ARAModelUpdateControllerInterface,
    instance: ARADocumentControllerHostInstance,
}

impl Host {
    unsafe fn new() -> Box<Host> {
        let mut host = Box::new(Host {
            audio_access: ARAAudioAccessControllerInterface {
                structSize: std::mem::size_of::<ARAAudioAccessControllerInterface>() as ARASize,
                createAudioReaderForSource: Some(create_audio_reader),
                readAudioSamples: Some(read_audio_samples),
                destroyAudioReader: Some(destroy_audio_reader),
            },
            archiving: ARAArchivingControllerInterface {
                structSize: std::mem::size_of::<ARAArchivingControllerInterface>() as ARASize,
                getArchiveSize: Some(get_archive_size),
                readBytesFromArchive: Some(read_bytes_from_archive),
                writeBytesToArchive: Some(write_bytes_to_archive),
                notifyDocumentArchivingProgress: Some(archiving_progress),
                notifyDocumentUnarchivingProgress: Some(archiving_progress),
                getDocumentArchiveID: Some(get_document_archive_id),
            },
            content_access: ARAContentAccessControllerInterface {
                structSize: std::mem::size_of::<ARAContentAccessControllerInterface>() as ARASize,
                isMusicalContextContentAvailable: Some(musical_context_content_available),
                getMusicalContextContentGrade: Some(musical_context_content_grade),
                createMusicalContextContentReader: Some(musical_context_content_reader),
                isAudioSourceContentAvailable: Some(audio_source_content_available),
                getAudioSourceContentGrade: Some(audio_source_content_grade),
                createAudioSourceContentReader: Some(audio_source_content_reader),
                getContentReaderEventCount: Some(content_reader_event_count),
                getContentReaderDataForEvent: Some(content_reader_data),
                destroyContentReader: Some(destroy_content_reader),
            },
            model_update: ARAModelUpdateControllerInterface {
                structSize: std::mem::size_of::<ARAModelUpdateControllerInterface>() as ARASize,
                notifyAudioSourceAnalysisProgress: Some(analysis_progress),
                notifyAudioSourceContentChanged: Some(audio_source_content_changed),
                notifyAudioModificationContentChanged: Some(audio_modification_content_changed),
                notifyPlaybackRegionContentChanged: Some(playback_region_content_changed),
                notifyDocumentDataChanged: Some(document_data_changed),
            },
            instance: std::mem::zeroed(),
        });
        // The host refs are opaque to the plug-in; the controllers need none of their own, so they are a token
        let token = 1usize as *mut core::ffi::c_void;
        let (aa, ar, ca, mu) = (&host.audio_access as *const _, &host.archiving as *const _, &host.content_access as *const _, &host.model_update as *const _);
        host.instance = ARADocumentControllerHostInstance {
            structSize: std::mem::size_of::<ARADocumentControllerHostInstance>() as ARASize,
            audioAccessControllerHostRef: token as _,
            audioAccessControllerInterface: aa,
            archivingControllerHostRef: token as _,
            archivingControllerInterface: ar,
            contentAccessControllerHostRef: token as _,
            contentAccessControllerInterface: ca,
            modelUpdateControllerHostRef: token as _,
            modelUpdateControllerInterface: mu,
            playbackControllerHostRef: std::ptr::null_mut(),
            playbackControllerInterface: std::ptr::null(),
        };
        host
    }
}

/// ARA initialised at generation 2.0 (the plug-in must speak it), as the SDK's MiniHost asks.
unsafe fn initialize(f: &ARAFactory) -> Result<(), String> {
    let generation = kARAAPIGeneration_2_0_Final as ARAAPIGeneration;
    if { f.lowestSupportedApiGeneration } > generation || { f.highestSupportedApiGeneration } < generation {
        return Err("the plug-in does not speak ARA 2.0".into());
    }
    let config = ARAInterfaceConfiguration { structSize: std::mem::size_of::<ARAInterfaceConfiguration>() as ARASize, desiredApiGeneration: generation, assertFunctionAddress: std::ptr::null_mut() };
    (f.initializeARAWithConfiguration.ok_or("no initializeARAWithConfiguration")?)(&config);
    Ok(())
}

/// One document round one file: a musical context, a region sequence, the file as an audio source, an audio
/// modification and a playback region spanning it, built in the SDK's MiniHost's order with the samples opened.
struct Doc {
    ctrl: ARADocumentControllerRef,
    dc: *const ARADocumentControllerInterface,
    context: ARAMusicalContextRef,
    sequence: ARARegionSequenceRef,
    source: ARAAudioSourceRef,
    modification: ARAAudioModificationRef,
    region: ARAPlaybackRegionRef,
}

macro_rules! call {
    ($doc:expr, $name:ident $(, $arg:expr)*) => { ({ (*$doc.dc).$name }.ok_or(concat!("no ", stringify!($name)))?)($doc.ctrl $(, $arg)*) };
}

impl Doc {
    unsafe fn build(f: &ARAFactory, host: &Host, source: &Source, rate: u32, frames: usize) -> Result<Doc, String> {
        let token = 1usize as *mut core::ffi::c_void;
        let doc_props = ARADocumentProperties { structSize: std::mem::size_of::<ARADocumentProperties>() as ARASize, name: c"formwav".as_ptr() };
        let instance = (f.createDocumentControllerWithDocument.ok_or("no createDocumentControllerWithDocument")?)(&host.instance, &doc_props);
        if instance.is_null() {
            return Err("the plug-in made no document controller".into());
        }
        let mut doc = Doc { ctrl: { (*instance).documentControllerRef }, dc: { (*instance).documentControllerInterface }, context: std::ptr::null_mut(), sequence: std::ptr::null_mut(), source: std::ptr::null_mut(), modification: std::ptr::null_mut(), region: std::ptr::null_mut() };
        call!(doc, beginEditing);
        let context_props = ARAMusicalContextProperties { structSize: std::mem::size_of::<ARAMusicalContextProperties>() as ARASize, name: std::ptr::null(), orderIndex: 0, color: std::ptr::null() };
        doc.context = call!(doc, createMusicalContext, token as _, &context_props);
        let sequence_props = ARARegionSequenceProperties { structSize: std::mem::size_of::<ARARegionSequenceProperties>() as ARASize, name: c"Track".as_ptr(), orderIndex: 0, musicalContextRef: doc.context, color: std::ptr::null() };
        doc.sequence = call!(doc, createRegionSequence, token as _, &sequence_props);
        let source_props = ARAAudioSourceProperties {
            structSize: std::mem::size_of::<ARAAudioSourceProperties>() as ARASize,
            name: c"Clip".as_ptr(),
            persistentID: c"formwav.clip.1".as_ptr(),
            sampleCount: frames as ARASampleCount,
            sampleRate: f64::from(rate),
            channelCount: source.channels.len() as ARAChannelCount,
            merits64BitSamples: 0,
            channelArrangementDataType: 0,
            channelArrangement: std::ptr::null(),
        };
        doc.source = call!(doc, createAudioSource, source as *const Source as ARAAudioSourceHostRef, &source_props);
        let modification_props = ARAAudioModificationProperties { structSize: std::mem::size_of::<ARAAudioModificationProperties>() as ARASize, name: c"Clip".as_ptr(), persistentID: c"formwav.clip.1.edit".as_ptr() };
        doc.modification = call!(doc, createAudioModification, doc.source, token as _, &modification_props);
        let seconds = frames as f64 / f64::from(rate.max(1));
        let region_props = ARAPlaybackRegionProperties {
            structSize: std::mem::size_of::<ARAPlaybackRegionProperties>() as ARASize,
            transformationFlags: kARAPlaybackTransformationNoChanges as ARAPlaybackTransformationFlags,
            startInModificationTime: 0.0,
            durationInModificationTime: seconds,
            startInPlaybackTime: 0.0,
            durationInPlaybackTime: seconds,
            musicalContextRef: doc.context,
            regionSequenceRef: doc.sequence,
            name: c"Clip".as_ptr(),
            color: std::ptr::null(),
        };
        doc.region = call!(doc, createPlaybackRegion, doc.modification, token as _, &region_props);
        call!(doc, endEditing);
        call!(doc, enableAudioSourceSamplesAccess, doc.source, 1);
        Ok(doc)
    }

    /// Everything the document holds, destroyed in reverse, then the document controller itself.
    unsafe fn teardown(&self) -> Result<(), String> {
        call!(self, enableAudioSourceSamplesAccess, self.source, 0);
        call!(self, beginEditing);
        call!(self, destroyPlaybackRegion, self.region);
        call!(self, destroyAudioModification, self.modification);
        call!(self, destroyAudioSource, self.source);
        call!(self, destroyRegionSequence, self.sequence);
        call!(self, destroyMusicalContext, self.context);
        call!(self, endEditing);
        call!(self, destroyDocumentController);
        Ok(())
    }
}

/// `fwhost ara-render <plugin.clap> <in.wav> <out.wav>`: the file's playback region rendered by the plug-in in ARA's
/// playback renderer role. A CLAP instance of it is bound to the document as playback renderer and given the region;
/// it is then processed with silence as its input and a playing transport at each block's position (as the SDK's own
/// CLAPRenderBuffer does), so everything it outputs comes from the document through ARA, not from its audio input.
pub fn render(path: &Path, input: crate::wav::Audio) -> Result<crate::wav::Audio, String> {
    unsafe {
        let opened = open(path)?;
        let f = &*opened.factory;
        initialize(f)?;
        let host = Host::new();
        let rate = input.rate;
        let frames = input.channels.first().map(|c| c.len()).unwrap_or(0);
        let channels = input.channels.len().max(1);
        let source = Source { channels: input.channels };
        let doc = Doc::build(f, &host, &source, rate, frames)?;

        let factory = ((*opened.entry).get_factory.ok_or("no get_factory")?)(CLAP_PLUGIN_FACTORY_ID.as_ptr()) as *const clap_plugin_factory;
        if factory.is_null() {
            return Err("no plug-in factory".into());
        }
        let clap_host = Box::new(clap_host {
            clap_version: CLAP_VERSION,
            host_data: std::ptr::null_mut(),
            name: c"formwav".as_ptr(),
            vendor: c"nodemode-ai".as_ptr(),
            url: c"https://github.com/nodemode-ai/formwav".as_ptr(),
            version: c"1".as_ptr(),
            get_extension: Some(crate::host_get_extension),
            request_restart: Some(crate::host_request),
            request_process: Some(crate::host_request),
            request_callback: Some(crate::host_request),
        });
        let plugin_id = CString::new(opened.plugin_id.clone()).map_err(|e| e.to_string())?;
        let plugin = ((*factory).create_plugin.ok_or("no create_plugin")?)(factory, &*clap_host, plugin_id.as_ptr());
        if plugin.is_null() || !((*plugin).init.ok_or("no init")?)(plugin) {
            return Err("the plug-in would not initialise".into());
        }
        let get_extension = (*plugin).get_extension.ok_or("no get_extension")?;
        let mut ext = get_extension(plugin, CLAP_EXT_ARA_PLUGINEXTENSION.as_ptr()) as *const clap_ara_plugin_extension;
        if ext.is_null() {
            ext = get_extension(plugin, CLAP_EXT_ARA_PLUGINEXTENSION_COMPAT.as_ptr()) as *const clap_ara_plugin_extension;
        }
        if ext.is_null() {
            return Err("the plug-in's instance offers no ARA extension".into());
        }
        let known = (kARAPlaybackRendererRole | kARAEditorRendererRole | kARAEditorViewRole) as ARAPlugInInstanceRoleFlags;
        let bound = ((*ext).bind_to_document_controller.ok_or("no bind_to_document_controller")?)(plugin, doc.ctrl, known, kARAPlaybackRendererRole as ARAPlugInInstanceRoleFlags);
        if bound.is_null() || { (*bound).playbackRendererInterface }.is_null() {
            return Err("the plug-in would not bind as playback renderer".into());
        }
        let renderer = &*{ (*bound).playbackRendererInterface };
        let renderer_ref = { (*bound).playbackRendererRef };
        ({ renderer.addPlaybackRegion }.ok_or("no addPlaybackRegion")?)(renderer_ref, doc.region);

        // The plug-in's main input and output configured to the file's channel count before it activates, as the SDK's
        // CLAPStartRendering does: left at its own layout, the test plug-in rendered a stereo file as a mono downmix.
        // One without the extension keeps two channels each way, a mono file taken from the first.
        let mut width = 2usize;
        let ports = get_extension(plugin, CLAP_EXT_CONFIGURABLE_AUDIO_PORTS.as_ptr()) as *const clap_plugin_configurable_audio_ports;
        if !ports.is_null() && (channels == 1 || channels == 2) {
            let port_type = if channels == 1 { CLAP_PORT_MONO.as_ptr() } else { CLAP_PORT_STEREO.as_ptr() };
            let request = |is_input: bool| clap_audio_port_configuration_request { is_input, port_index: 0, channel_count: channels as u32, port_type, port_details: std::ptr::null() };
            let requests = [request(true), request(false)];
            if !({ (*ports).apply_configuration }.ok_or("no apply_configuration")?)(plugin, requests.as_ptr(), requests.len() as u32) {
                return Err(format!("the plug-in refused a {channels}-channel layout"));
            }
            width = channels;
        }
        if !((*plugin).activate.ok_or("no activate")?)(plugin, f64::from(rate), 1, RENDER_BLOCK as u32) || !((*plugin).start_processing.ok_or("no start_processing")?)(plugin) {
            return Err("the plug-in would not start".into());
        }
        let no_events = crate::params::ClapEvents::new(&[]);
        let in_events = clap_input_events { ctx: &no_events as *const crate::params::ClapEvents as *mut core::ffi::c_void, size: Some(crate::params::clap_events_size), get: Some(crate::params::clap_events_get) };
        let out_events = clap_output_events { ctx: std::ptr::null_mut(), try_push: Some(crate::no_events_push) };
        let silence = vec![0f32; RENDER_BLOCK];
        let mut out = vec![vec![0f32; frames]; width];
        let mut pos = 0;
        while pos < frames {
            let n = RENDER_BLOCK.min(frames - pos);
            let mut in_ptrs: Vec<*mut f32> = (0..width).map(|_| silence.as_ptr() as *mut f32).collect();
            let mut out_ptrs: Vec<*mut f32> = out.iter_mut().map(|c| c.as_mut_ptr().add(pos)).collect();
            let in_buf = clap_audio_buffer { data32: in_ptrs.as_mut_ptr(), data64: std::ptr::null_mut(), channel_count: width as u32, latency: 0, constant_mask: u64::MAX };
            let mut out_buf = clap_audio_buffer { data32: out_ptrs.as_mut_ptr(), data64: std::ptr::null_mut(), channel_count: width as u32, latency: 0, constant_mask: 0 };
            let mut transport: clap_event_transport = std::mem::zeroed();
            transport.header = clap_event_header { size: std::mem::size_of::<clap_event_transport>() as u32, time: 0, space_id: CLAP_CORE_EVENT_SPACE_ID, type_: CLAP_EVENT_TRANSPORT, flags: 0 };
            transport.flags = CLAP_TRANSPORT_HAS_SECONDS_TIMELINE | CLAP_TRANSPORT_IS_PLAYING;
            transport.song_pos_seconds = (CLAP_SECTIME_FACTOR as f64 * (pos as f64 / f64::from(rate))).round() as i64;
            let process = clap_process {
                steady_time: pos as i64,
                frames_count: n as u32,
                transport: &transport,
                audio_inputs: &in_buf,
                audio_outputs: &mut out_buf,
                audio_inputs_count: 1,
                audio_outputs_count: 1,
                in_events: &in_events,
                out_events: &out_events,
            };
            if ((*plugin).process.ok_or("no process")?)(plugin, &process) == CLAP_PROCESS_ERROR {
                return Err(format!("the plug-in failed at frame {pos}"));
            }
            pos += n;
        }
        ((*plugin).stop_processing.ok_or("no stop_processing")?)(plugin);
        ((*plugin).deactivate.ok_or("no deactivate")?)(plugin);
        ({ renderer.removePlaybackRegion }.ok_or("no removePlaybackRegion")?)(renderer_ref, doc.region);
        ((*plugin).destroy.ok_or("no destroy")?)(plugin);
        drop(clap_host);
        doc.teardown()?;
        if let Some(uninit) = f.uninitializeARA {
            uninit();
        }
        drop(opened);
        out.truncate(channels.min(2));
        Ok(crate::wav::Audio { rate, channels: out })
    }
}

/// `fwhost ara-analyze <plugin.clap> <in.wav>`: an ARA document built round the file (Doc), its samples opened to the
/// plug-in, note analysis requested and waited for (model updates delivered while it runs), and the notes it found
/// read back, as JSON.
pub fn analyze(path: &Path, input: crate::wav::Audio) -> Result<String, String> {
    unsafe {
        let opened = open(path)?;
        let f = &*opened.factory;
        initialize(f)?;
        let host = Host::new();
        let frames = input.channels.first().map(|c| c.len()).unwrap_or(0);
        let rate = input.rate;
        let source = Source { channels: input.channels };
        let channel_count = source.channels.len();
        let doc = Doc::build(f, &host, &source, rate, frames)?;
        let audio_source = doc.source;

        PROGRESS_EVENTS.store(0, std::sync::atomic::Ordering::Relaxed);
        CONTENT_EVENTS.store(0, std::sync::atomic::Ordering::Relaxed);
        let notes_type = kARAContentTypeNotes as ARAContentType;
        call!(doc, requestAudioSourceContentAnalysis, audio_source, 1, &notes_type);
        let started = std::time::Instant::now();
        let mut finished = false;
        while started.elapsed().as_secs_f64() < 120.0 {
            call!(doc, notifyModelUpdates);
            if call!(doc, isAudioSourceContentAnalysisIncomplete, audio_source, notes_type) == 0 {
                finished = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        call!(doc, notifyModelUpdates);
        let analysis_seconds = started.elapsed().as_secs_f64();

        let mut notes = Vec::new();
        let available = call!(doc, isAudioSourceContentAvailable, audio_source, notes_type) != 0;
        if available {
            let reader = call!(doc, createAudioSourceContentReader, audio_source, notes_type, std::ptr::null());
            if !reader.is_null() {
                let count = call!(doc, getContentReaderEventCount, reader);
                for i in 0..count {
                    let p = call!(doc, getContentReaderDataForEvent, reader, i) as *const ARAContentNote;
                    if p.is_null() {
                        continue;
                    }
                    let n = std::ptr::read_unaligned(p);
                    notes.push(format!(
                        "{{\"frequency\": {}, \"pitch\": {}, \"volume\": {:.6}, \"start_s\": {:.6}, \"duration_s\": {:.6}, \"signal_s\": {:.6}}}",
                        { n.frequency },
                        { n.pitchNumber },
                        { n.volume },
                        { n.startPosition },
                        { n.noteDuration },
                        { n.signalDuration }
                    ));
                }
                call!(doc, destroyContentReader, reader);
            }
        }
        doc.teardown()?;
        if let Some(uninit) = f.uninitializeARA {
            uninit();
        }
        let plugin_id = opened.plugin_id.clone();
        drop(opened);
        Ok(format!(
            "{{\"plugin_id\": \"{}\", \"frames\": {}, \"rate\": {}, \"channels\": {}, \"analysis\": {{\"finished\": {}, \"seconds\": {:.3}, \"progress_events\": {}, \"content_events\": {}, \"notes_available\": {}, \"notes\": [{}]}}}}",
            esc(&plugin_id),
            frames,
            rate,
            channel_count,
            finished,
            analysis_seconds,
            PROGRESS_EVENTS.load(std::sync::atomic::Ordering::Relaxed),
            CONTENT_EVENTS.load(std::sync::atomic::Ordering::Relaxed),
            available,
            notes.join(", ")
        ))
    }
}

/// `fwhost ara-check <plugin.clap>`: the plug-in's ARA factories as JSON (`ara` false when it offers none).
pub fn check(path: &Path) -> Result<String, String> {
    unsafe {
        let lib = libloading::Library::new(path).map_err(|e| format!("cannot load {}: {e}", path.display()))?;
        let entry: libloading::Symbol<*const clap_plugin_entry> = lib.get(b"clap_entry\0").map_err(|e| format!("no clap_entry: {e}"))?;
        let entry = &**entry;
        let cpath = CString::new(path.to_string_lossy().as_bytes()).map_err(|e| e.to_string())?;
        if !(entry.init.ok_or("entry without init")?)(cpath.as_ptr()) {
            return Err("the plug-in's entry refused to initialise".into());
        }
        let get = entry.get_factory.ok_or("entry without get_factory")?;
        let mut extension = CLAP_EXT_ARA_FACTORY;
        let mut ara = get(CLAP_EXT_ARA_FACTORY.as_ptr()) as *const clap_ara_factory;
        if ara.is_null() {
            extension = CLAP_EXT_ARA_FACTORY_COMPAT;
            ara = get(CLAP_EXT_ARA_FACTORY_COMPAT.as_ptr()) as *const clap_ara_factory;
        }
        let mut factories = Vec::new();
        if !ara.is_null() {
            let count = (*ara).get_factory_count.map(|g| g(ara)).unwrap_or(0);
            for index in 0..count {
                let Some(f) = (*ara).get_ara_factory.map(|g| g(ara, index)).filter(|f| !f.is_null()) else { continue };
                let plugin_id = (*ara).get_plugin_id.map(|g| text(g(ara, index))).unwrap_or_default();
                factories.push(factory_json(&*f, &plugin_id));
            }
        }
        if let Some(deinit) = entry.deinit {
            deinit();
        }
        drop(lib);
        Ok(format!(
            "{{\"path\": \"{}\", \"ara\": {}, \"extension\": {}, \"factories\": [{}]}}",
            esc(&path.display().to_string()),
            !factories.is_empty(),
            if factories.is_empty() { "null".to_string() } else { format!("\"{}\"", esc(&extension.to_string_lossy())) },
            factories.join(", ")
        ))
    }
}
